"use client";

import { cn } from "@/lib/utils";
import { ArrowLeft, ChevronLeft, ChevronRight } from "lucide-react";
import React, { useLayoutEffect, useRef, useState } from "react";
import { getThemeStyles } from "./date-picker-theme";
import { springLinear } from "./motion-curves";

// ==========================================
// CALENDAR PANEL
// The month grid shared by every DatePickerBlock variant: a header with
// prev / next, a month + year picker behind the title, and a fixed-height
// stage so the card never changes size — not between 5- and 6-week months and
// not between the calendar and the picker. Pages slide into each other slowly
// on the Web Animations API (no animation library); the selected day's pill
// glides on a CSS spring. Reduced motion: everything is instant.
// ==========================================

const MONTH_NAMES = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];
const DAY_NAMES = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

const YEAR_MIN = 1900;
const YEAR_MAX = 2100;
const YEARS = Array.from({ length: YEAR_MAX - YEAR_MIN + 1 }, (_, i) => YEAR_MIN + i);

/** Weekday row (2rem) + six week rows (2.5rem each). Never changes. */
const STAGE_PX = 272;

/** Slide between pages: slow and lazy, the page travels 56% of its width while fading. */
const SLIDE_MS = 640;
const SLIDE_EASE = "cubic-bezier(0.32, 0.72, 0, 1)";
const SLIDE_OFFSET = 56;

const UNFOLD = springLinear({ stiffness: 240, damping: 30, mass: 0.9 });
const unfoldOn = (property: string) => `${property} ${UNFOLD.duration}ms ${UNFOLD.easing}`;

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const isSameDay = (a: Date, b: Date) =>
  a.getDate() === b.getDate() && a.getMonth() === b.getMonth() && a.getFullYear() === b.getFullYear();

/** Always 42 cells (six weeks) so the grid height never moves. */
const generateCalendarDays = (year: number, month: number, weekStartsOn: 0 | 1) => {
  const lead = (new Date(year, month, 1).getDay() - weekStartsOn + 7) % 7;
  const daysInMonth = getDaysInMonth(year, month);
  const daysInPrevMonth = getDaysInMonth(year, month - 1);
  const days: { date: Date; isCurrentMonth: boolean }[] = [];
  for (let i = lead - 1; i >= 0; i--) {
    days.push({ date: new Date(year, month - 1, daysInPrevMonth - i), isCurrentMonth: false });
  }
  for (let i = 1; i <= daysInMonth; i++) {
    days.push({ date: new Date(year, month, i), isCurrentMonth: true });
  }
  for (let i = 1; days.length < 42; i++) {
    days.push({ date: new Date(year, month + 1, i), isCurrentMonth: false });
  }
  return days;
};

type Page = { kind: "days"; year: number; month: number } | { kind: "months" };
const pageKey = (p: Page) => (p.kind === "months" ? "months" : `${p.year}-${p.month}`);

/** +1 when `to` sits after `from` (slides in from the right), -1 otherwise. */
const directionBetween = (from: Page, to: Page): 1 | -1 => {
  if (to.kind === "months") return 1;
  if (from.kind === "months") return -1;
  return to.year * 12 + to.month >= from.year * 12 + from.month ? 1 : -1;
};

const slide = (el: HTMLElement, from: number, to: number) =>
  el.animate(
    [
      { transform: `translateX(${from}%)`, opacity: from === 0 ? 1 : 0 },
      { transform: `translateX(${to}%)`, opacity: to === 0 ? 1 : 0 },
    ],
    { duration: SLIDE_MS, easing: SLIDE_EASE, fill: "backwards" },
  );

/**
 * The pill behind the selected day. One element that glides to the newly
 * picked day on the unfold spring: after each change it measures the day
 * marked `data-selected` inside the grid and moves there. It jumps, without
 * gliding, on first show and when the month changes.
 */
function SelectionPill({
  selectedKey,
  monthKey,
  instant,
  className,
}: {
  selectedKey: string | null;
  monthKey: string;
  instant: boolean;
  className?: string;
}) {
  const pillRef = useRef<HTMLSpanElement>(null);
  const placedIn = useRef<string | null>(null);

  useLayoutEffect(() => {
    const pill = pillRef.current;
    const grid = pill?.parentElement;
    if (!grid || !pill) return;
    const place = (glide: boolean) => {
      const target = grid.querySelector<HTMLElement>('[data-selected="true"]');
      if (!target) {
        pill.style.opacity = "0";
        placedIn.current = null;
        return;
      }
      const from = grid.getBoundingClientRect();
      const to = target.getBoundingClientRect();
      // Screen pixels vs the grid's own CSS pixels: divide any ancestor scale out.
      const scale = grid.offsetWidth > 0 ? from.width / grid.offsetWidth : 1;
      pill.style.transition = glide ? unfoldOn("transform") : "none";
      pill.style.transform = `translate(${(to.left - from.left) / scale}px, ${(to.top - from.top) / scale}px)`;
      pill.style.opacity = "1";
      placedIn.current = monthKey;
    };
    place(placedIn.current === monthKey && !instant);

    // Snap back onto the day if the grid is resized after the pill is placed.
    let initial = true;
    const observer = new ResizeObserver(() => {
      if (initial) {
        initial = false;
        return;
      }
      place(false);
    });
    observer.observe(grid);
    return () => observer.disconnect();
  }, [selectedKey, monthKey, instant]);

  return (
    <span
      ref={pillRef}
      aria-hidden
      className={cn(
        "pointer-events-none absolute left-0 top-0 z-0 size-9 rounded-full opacity-0 shadow-xs",
        className,
      )}
    />
  );
}

/** The long, scrolling year column; opens already centred on the active year. */
function YearList({
  activeYear,
  pickYear,
  todayYear,
  isYearDisabled,
  onPick,
  activeClass,
}: {
  activeYear: number;
  pickYear: number;
  todayYear: number;
  isYearDisabled: (year: number) => boolean;
  onPick: (year: number) => void;
  activeClass: string;
}) {
  const listRef = useRef<HTMLDivElement>(null);
  const activeRef = useRef<HTMLButtonElement>(null);

  useLayoutEffect(() => {
    const list = listRef.current;
    const item = activeRef.current;
    if (!list || !item) return;
    list.scrollTop = item.offsetTop - list.clientHeight / 2 + item.offsetHeight / 2;
  }, []);

  return (
    <div
      ref={listRef}
      className="h-full w-20 shrink-0 overflow-y-auto border-r border-border/60 pr-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
    >
      <div className="flex flex-col gap-0.5 py-1">
        {YEARS.map((year) => {
          const isPicked = year === pickYear;
          const off = isYearDisabled(year);
          return (
            <button
              key={year}
              ref={year === activeYear ? activeRef : undefined}
              type="button"
              disabled={off}
              aria-pressed={isPicked}
              onClick={() => onPick(year)}
              className={cn(
                "h-9 shrink-0 rounded-lg text-sm tabular-nums transition-colors duration-200",
                isPicked
                  ? cn(activeClass, "font-semibold")
                  : cn(
                      "font-medium text-foreground hover:bg-muted",
                      year === todayYear && "ring-1 ring-inset ring-border",
                    ),
                off && "cursor-not-allowed text-muted-foreground/40 line-through hover:bg-transparent",
              )}
            >
              {year}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export interface CalendarPanelProps {
  /** Any day inside the month being shown. */
  viewDate: Date;
  onViewDateChange: (date: Date) => void;
  value?: Date | null;
  /** Fired with the clicked day (midnight). The caller decides what to keep. */
  onSelect: (date: Date) => void;
  isDayDisabled?: (date: Date) => boolean;
  /** Earliest / latest selectable moment, used to grey out whole months and years. */
  lower?: Date | null;
  upper?: Date | null;
  color?: string;
  /** 1 = Monday first (default), 0 = Sunday first. */
  weekStartsOn?: 0 | 1;
  reduceMotion?: boolean;
  /** False while the card is hidden (a closed popover): resets to the calendar page without animating. */
  active?: boolean;
  className?: string;
}

export function CalendarPanel({
  viewDate,
  onViewDateChange,
  value,
  onSelect,
  isDayDisabled,
  lower = null,
  upper = null,
  color = "primary",
  weekStartsOn = 1,
  reduceMotion = false,
  active = true,
  className,
}: CalendarPanelProps) {
  const { theme } = getThemeStyles(color);
  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const today = new Date();

  const [view, setView] = useState<"days" | "months">("days");
  const [pickYear, setPickYear] = useState(year);
  if (!active && view !== "days") setView("days");

  // --- Page transitions ---
  // The page on show is derived from state; when it changes, the page it
  // replaces stays mounted (inert) while both slide, then is dropped.
  const page: Page = view === "months" ? { kind: "months" } : { kind: "days", year, month };
  const key = pageKey(page);
  const [shown, setShown] = useState<Page>(page);
  const [leaving, setLeaving] = useState<{ page: Page; dir: 1 | -1 } | null>(null);
  if (pageKey(shown) !== key) {
    setShown(page);
    if (active && !reduceMotion) setLeaving({ page: shown, dir: directionBetween(shown, page) });
    else if (leaving) setLeaving(null);
  }

  const leavingRef = useRef<HTMLDivElement>(null);
  const currentRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    if (!leaving) return;
    const out = leavingRef.current;
    const inn = currentRef.current;
    if (!out || !inn) return;
    const animations = [
      slide(out, 0, -leaving.dir * SLIDE_OFFSET),
      slide(inn, leaving.dir * SLIDE_OFFSET, 0),
    ];
    let live = true;
    Promise.all(animations.map((a) => a.finished))
      .then(() => {
        if (live) setLeaving(null);
      })
      .catch(() => {});
    return () => {
      live = false;
      animations.forEach((a) => a.cancel());
    };
  }, [leaving]);

  // --- Navigation ---
  const goToMonth = (delta: number) => onViewDateChange(new Date(year, month + delta, 1));
  const openPicker = () => {
    setPickYear(year);
    setView("months");
  };
  const pickMonth = (m: number) => {
    onViewDateChange(new Date(pickYear, m, 1));
    setView("days");
  };

  const isYearDisabled = (y: number) =>
    (lower !== null && new Date(y, 11, 31, 23, 59, 59, 999) < lower) ||
    (upper !== null && new Date(y, 0, 1) > upper);
  const isMonthDisabled = (y: number, m: number) =>
    (lower !== null && new Date(y, m + 1, 0, 23, 59, 59, 999) < lower) ||
    (upper !== null && new Date(y, m, 1) > upper);

  const selectedText =
    color === "zinc"
      ? "text-white dark:text-zinc-900"
      : color === "primary"
        ? "text-primary-foreground"
        : "text-white";
  const weekdays = weekStartsOn === 1 ? [...DAY_NAMES.slice(1), DAY_NAMES[0]] : DAY_NAMES;

  const renderPage = (p: Page) => {
    if (p.kind === "months") {
      return (
        <div className="flex h-full gap-3">
          <YearList
            activeYear={year}
            pickYear={pickYear}
            todayYear={today.getFullYear()}
            isYearDisabled={isYearDisabled}
            onPick={setPickYear}
            activeClass={theme.bg}
          />
          <div className="grid min-w-0 flex-1 grid-cols-2 grid-rows-6 gap-1">
            {MONTH_NAMES.map((name, m) => {
              const isActive = pickYear === year && m === month;
              const off = isMonthDisabled(pickYear, m);
              const isThisMonth = pickYear === today.getFullYear() && m === today.getMonth();
              return (
                <button
                  key={name}
                  type="button"
                  disabled={off}
                  aria-pressed={isActive}
                  onClick={() => pickMonth(m)}
                  className={cn(
                    "rounded-lg px-1 text-sm transition-colors duration-200",
                    isActive
                      ? cn(theme.bg, "font-semibold")
                      : cn(
                          "font-medium text-foreground hover:bg-muted",
                          isThisMonth && "ring-1 ring-inset ring-border",
                        ),
                    off && "cursor-not-allowed text-muted-foreground/40 line-through hover:bg-transparent",
                  )}
                >
                  {name}
                </button>
              );
            })}
          </div>
        </div>
      );
    }

    const cells = generateCalendarDays(p.year, p.month, weekStartsOn);
    return (
      <div>
        <div className="grid h-8 grid-cols-7 items-center text-center">
          {weekdays.map((d) => (
            <span key={d} className="text-xs font-medium text-muted-foreground">
              {d}
            </span>
          ))}
        </div>
        <div className="relative grid grid-cols-7 text-center">
          <SelectionPill
            selectedKey={
              value ? `${value.getFullYear()}-${value.getMonth()}-${value.getDate()}` : null
            }
            monthKey={`${p.year}-${p.month}`}
            instant={reduceMotion}
            className={theme.bg}
          />
          {cells.map(({ date, isCurrentMonth }, i) => {
            const isSelected = Boolean(value && isSameDay(date, value));
            const isToday = isSameDay(date, today);
            const off = isDayDisabled?.(date) ?? false;
            return (
              <div key={i} className="flex h-10 items-center justify-center">
                <button
                  type="button"
                  disabled={off}
                  aria-disabled={off}
                  aria-pressed={isSelected}
                  aria-label={new Intl.DateTimeFormat("en-US", { dateStyle: "full" }).format(date)}
                  data-selected={isSelected ? "true" : undefined}
                  onClick={() => {
                    if (off) return;
                    onSelect(date);
                    if (!isCurrentMonth) onViewDateChange(new Date(date.getFullYear(), date.getMonth(), 1));
                  }}
                  className={cn(
                    "relative flex size-9 items-center justify-center rounded-full text-sm leading-none transition-colors duration-300",
                    isSelected
                      ? cn(selectedText, "font-bold")
                      : cn(
                          "hover:bg-muted",
                          isCurrentMonth ? "font-medium text-foreground" : "font-medium text-muted-foreground/40",
                          isToday && "ring-1 ring-inset ring-border",
                        ),
                    off && "cursor-not-allowed font-normal text-muted-foreground/40 line-through hover:bg-transparent",
                  )}
                >
                  <span className="relative z-10">{date.getDate()}</span>
                </button>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  const navButton =
    "flex size-9 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-muted hover:text-foreground";

  return (
    <div className={cn("w-full select-none", className)}>
      <header className="mb-3 flex h-9 items-center justify-between">
        {view === "months" ? (
          <button type="button" aria-label="Back to calendar" onClick={() => setView("days")} className={navButton}>
            <ArrowLeft className="size-4" />
          </button>
        ) : (
          <button type="button" aria-label="Previous month" onClick={() => goToMonth(-1)} className={navButton}>
            <ChevronLeft className="size-4" />
          </button>
        )}

        <button
          type="button"
          aria-label="Choose month and year"
          aria-expanded={view === "months"}
          onClick={() => (view === "months" ? setView("days") : openPicker())}
          className="rounded-lg px-3 py-1 text-[15px] font-bold tracking-tight text-foreground transition-colors hover:bg-muted"
        >
          {view === "months" ? pickYear : `${MONTH_NAMES[month]} ${year}`}
        </button>

        {view === "months" ? (
          <span aria-hidden className="size-9" />
        ) : (
          <button type="button" aria-label="Next month" onClick={() => goToMonth(1)} className={navButton}>
            <ChevronRight className="size-4" />
          </button>
        )}
      </header>

      <div className="relative overflow-hidden" style={{ height: STAGE_PX }}>
        {leaving && (
          <div
            key={pageKey(leaving.page)}
            ref={leavingRef}
            inert
            aria-hidden
            className="pointer-events-none absolute inset-0"
          >
            {renderPage(leaving.page)}
          </div>
        )}
        <div key={key} ref={currentRef} className="absolute inset-0">
          {renderPage(page)}
        </div>
      </div>
    </div>
  );
}

"use client";

import React from "react";

const colorThemes: Record<string, Record<string, string>> = {
  primary: {
    ring: "focus-within:ring-primary/30 focus-within:border-primary/30",
    text: "text-primary",
    bg: "bg-primary text-primary-foreground hover:bg-primary/90",
    bgSoft:
      "bg-primary/10 text-foreground hover:bg-primary/20",
    glow: "focus-within:shadow-[0_0_20px_var(--primary)] focus-within:border-primary/30",
  },
  indigo: {
    ring: "focus-within:ring-indigo-500/30 focus-within:border-indigo-500",
    text: "text-indigo-600 dark:text-indigo-400",
    bg: "bg-indigo-600 text-white hover:bg-indigo-700",
    bgSoft:
      "bg-indigo-50 dark:bg-indigo-500/10 text-indigo-900 dark:text-indigo-100 hover:bg-indigo-100 dark:hover:bg-indigo-500/20",
    glow: "focus-within:shadow-[0_0_20px_rgba(99,102,241,0.4)] focus-within:border-indigo-500",
  },
  rose: {
    ring: "focus-within:ring-rose-500/30 focus-within:border-rose-500",
    text: "text-rose-600 dark:text-rose-400",
    bg: "bg-rose-600 text-white hover:bg-rose-700",
    bgSoft:
      "bg-rose-50 dark:bg-rose-500/10 text-rose-900 dark:text-rose-100 hover:bg-rose-100 dark:hover:bg-rose-500/20",
    glow: "focus-within:shadow-[0_0_20px_rgba(244,63,94,0.4)] focus-within:border-rose-500",
  },
  emerald: {
    ring: "focus-within:ring-emerald-500/30 focus-within:border-emerald-500",
    text: "text-emerald-600 dark:text-emerald-400",
    bg: "bg-emerald-600 text-white hover:bg-emerald-700",
    bgSoft:
      "bg-emerald-50 dark:bg-emerald-500/10 text-emerald-900 dark:text-emerald-100 hover:bg-emerald-100 dark:hover:bg-emerald-500/20",
    glow: "focus-within:shadow-[0_0_20px_rgba(16,185,129,0.4)] focus-within:border-emerald-500",
  },
  zinc: {
    ring: "focus-within:ring-zinc-500/30 focus-within:border-zinc-500 dark:focus-within:ring-white/20 dark:focus-within:border-white",
    text: "text-zinc-900 dark:text-zinc-100",
    bg: "bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 hover:bg-zinc-800 dark:hover:bg-zinc-200",
    bgSoft:
      "bg-zinc-100 dark:bg-zinc-800/50 text-zinc-900 dark:text-zinc-100 hover:bg-zinc-200 dark:hover:bg-zinc-800",
    glow: "focus-within:shadow-[0_0_20px_rgba(255,255,255,0.15)] focus-within:border-zinc-900 dark:focus-within:border-white",
  },
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

export const getThemeStyles = (color: string) => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: {
        ring: "focus-within:ring-[var(--theme-color)]/30 focus-within:border-[var(--theme-color)]",
        text: "text-[var(--theme-color)]",
        bg: "bg-[var(--theme-color)] text-white hover:opacity-90",
        bgSoft:
          "bg-[rgba(var(--theme-color-rgb),0.1)] text-[var(--theme-color)] hover:bg-[rgba(var(--theme-color-rgb),0.2)]",
        glow: "focus-within:shadow-[0_0_20px_rgba(var(--theme-color-rgb),0.5)] focus-within:border-[var(--theme-color)]",
      },
      style: {
        "--theme-color": color,
        "--theme-color-rgb": rgb,
      } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] || colorThemes.primary, style: {} };
};

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
